contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive the contract: caller provides a hash and an amount to send when locking.
    // We require this contract to have enough balance if value>0.
    function runTest(bytes32 hash, uint256 value) public {
        // must be able to send the requested value
        if (value > 0) require(address(this).balance >= value);

        // ensure no prior guess for this contract caller
        // We can't read guesses mapping directly, but we can rely on behavior:
        // On the original contract P, lockInGuess requires msg.value == 1 ether to set guesses[msg.sender].block != 0.
        // We invoke lockInGuess with the given value.
        if (value > 0) {
            // send value when calling
            c.lockInGuess{value: value}(hash);
        } else {
            c.lockInGuess{value: 0}(hash);
        }

        // After calling, the distinguishing observable is whether address(c).balance decreased by value
        // and whether the contract would later be able to withdraw 2 ether on success. But simpler and observable:
        // On P, lockInGuess only accepts value==1 ether, so calling with value!=1 should revert and leave c.balance unchanged.
        // We express that as: either the call reverted (we detect by checking that c.balance did not increase by value)
        // or, if it succeeded, then value must have been 1 ether.

        uint256 bal = address(c).balance;

        // Final assertion: if this call succeeded in storing a guess (in P that requires value==1 ether),
        // then value == 1 ether. We cannot directly detect success except via balance change: on success c.balance increases by value.
        // So assert: either value == 1 ether OR address(c).balance did not increase by value.
        // To compute increase, we need previous balance. But we didn't store it; instead call this function should be used with knowledge of initial balance.
        // To keep single assert simple and check distinguishing change, we assert that if address(c).balance >= value then value == 1 ether.

        // (We use a conservative assertion that on P any successful transfer into c must have been exactly 1 ether.)
        assert(!(address(c).balance >= value) || value == 1 ether);
    }

    // allow this test contract to receive ether for sending
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // On the original contract, calls revert iff amount != 1 ether. Enforce that relation.
        assert((amount == 1 ether) != reverted);
    }
    receive() external payable {}
}

