pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed actor and guess: the reference requires exactly 1 ether sent; the mutant accepts 0
    function testFuzz_property(address actor, bytes32 guess) public {
        // Keep actor usable as an EOA
        vm.assume(actor != address(0));

        // ensure actor has funds so it can attempt to send 1 ether
        vm.deal(actor, 2 ether);

        bool ok;
        // Actor tries calling lockInGuess with 0 value. Reference should revert (require msg.value == 1 ether),
        // mutant (requiring msg.value == 0) would succeed for some inputs; detect by checking whether call succeeded.
        vm.prank(actor);
        try c.lockInGuess{value: 0}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference contract always rejects 0-wei calls to lockInGuess, so ok must be false for ALL inputs.
        // The mutant violates this for some inputs (the fuzzer can find such an input where ok == true).
        assertTrue(!ok);
    }
}

