pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz params: actor (caller address), value (amount sent), guess (bytes32 hash)
    function testFuzz_property(address actor, uint256 value, bytes32 guess) public {
        // Keep actor non-zero to be a valid EOA
        vm.assume(actor != address(0));
        // Bound value to a reasonable range (0 .. 10 ether) to allow finding differing behavior
        value = bound(value, 0, 10 ether);

        // Fund the actor so it can send the value
        vm.deal(actor, value + 1 ether);

        // Make the call as the actor and record whether it succeeds (does not revert)
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: value}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract records a guess (guesses[actor].block != 0) iff the call succeeded AND exactly 1 ether was sent.
        // Because we cannot read internal mapping directly, we observe by attempting to call settle: settle requires guesses[actor].block != 0
        // We call settle from the same actor; if settle reverts due to guesses[actor].block == 0, we treat that as not recorded.

        bool recorded;
        vm.prank(actor);
        try c.settle() {
            // settle succeeded (either paid out or not) -> the guess must have been recorded (block != 0)
            recorded = true;
        } catch {
            // settle reverted -> likely guesses[actor].block == 0 (not recorded) or block timing; to avoid block timing issues,
            // we only treat recorded == false here. This is acceptable because on the reference, lockInGuess only succeeds when value==1 ether,
            // so when value!=1 ether the call reverted and settle will not be callable.
            recorded = false;
        }

        // General rule (single assert): On the reference, for all inputs, recorded == (value == 1 ether && ok == true)
        // But on the mutant there exist inputs with value != 1 ether where ok==true and recorded==true; thus the assertion will fail on the mutant for some fuzz input.
        assertTrue(recorded == (value == 1 ether && ok));
    }
}

