pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and an arbitrary bytes32 guess
    function testFuzz_property(address caller, bytes32 guess) public {
        // keep caller non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Fund the caller so it can send 1 ether
        vm.deal(caller, 2 ether);

        // record the current block number
        uint256 before = block.number;

        // have the caller call lockInGuess sending exactly 1 ether
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // After call, read the stored block for caller via the public auto-generated getter
        // The reference implementation sets stored block to block.number + 1 at time of call,
        // so the stored value must be strictly greater than the block number at which the call executed (before)
        // We assert that stored block > before (a universal property true for the reference, false for the mutant for some inputs)
        (uint256 storedBlock, bytes32 storedGuess) = _readGuess(c, caller);

        // single assertion reading c's public surface
        assertTrue(storedBlock > before);
    }

    // helper to read the struct via public mapping getter; since mapping is mapping(address => Guess) guesses;
    // solidity generates a getter guesses(address) returns (uint256 block, bytes32 guess)
    function _readGuess(C _c, address who) internal view returns (uint256, bytes32) {
        // Call the auto-generated getter
        return _c.guesses(who);
    }
}

