pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: actor address and a bytes32 guess
    function testFuzz_property(address player, bytes32 guess) public {
        // admissible: player must be non-zero and a distinct EOA we can fund
        vm.assume(player != address(0));

        // fund the player so they can pay 1 ether
        vm.deal(player, 2 ether);

        // run as the player and call lockInGuess paying exactly 1 ether
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // read the recorded block for that player via the public auto-generated getter
        // the reference implementation stores block.number + 1, so it must be strictly > current block
        // We assert that stored block > block.number
        // This is the single assertion required. The mutant that stores block.number will make it equal
        // to block.number and thus violate this property for some inputs (found by the fuzzer).
        (, uint256 recordedBlock) = _getGuess(player);
        assertTrue(recordedBlock > block.number);
    }

    // helper to read the (guess, block) pair via low-level call to the public getter
    // because the contract C defines `mapping(address => Guess) guesses;` with struct Guess { uint block; bytes32 guess; }
    // the compiler generates a public getter guesses(address) returning (uint, bytes32) but ordering can be (uint, bytes32) or (bytes32, uint)
    // To be robust we call the getter as ABI and decode accordingly by matching expected types.
    function _getGuess(address who) internal returns (bytes32, uint256) {
        // call the autogenerated getter: guesses(address)
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("guesses(address)", who));
        require(ok, "getter failed");
        // The reference C declared struct Guess { uint block; bytes32 guess; }
        // The public getter returns (uint, bytes32) in that order. Decode accordingly.
        (uint256 b, bytes32 g) = abi.decode(ret, (uint256, bytes32));
        return (g, b);
    }
}

