pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz caller address and an offset for when to lock/settle to ensure blockhash is available
    function testFuzz_property(address player, uint256 offset) public {
        // Keep player non-zero and avoid the deploying address to be safe
        vm.assume(player != address(0));
        vm.assume(offset > 0 && offset < 256); // blockhash only available up to 256 blocks

        // Fund player
        vm.deal(player, 5 ether);

        // Compute a guess that will match the future blockhash: we will lock a guess equal to the keccak of the blockhash at the target block
        uint256 current = block.number;
        uint256 targetBlock = current + 1; // lockInGuess sets stored block = block.number + 1
        // We want settle to run at block > stored block and compute answer = keccak256(blockhash(stored block))
        // So we will advance to targetBlock + offset, and compute the guess using the blockhash of stored block at runtime is not available in test
        // Instead, we simulate winning by performing lockInGuess at some block, then capturing the actual blockhash of that stored block after mining one block

        // Prank as player to call lockInGuess with 1 ether
        bytes32 placeholder = bytes32(uint256(0));
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(placeholder);

        // Determine stored block (it's block.number + 1 at time of lockInGuess). We read it via attempting settle behaviour indirectly by computing when to call settle.
        // Advance one block so the stored block exists and blockhash(stored) is available
        vm.roll(block.number + 1);

        // Now we need to know the stored block number to compute the correct guess to match the answer.
        // We can't directly read the mapping, but we can re-lock from another freshly funded address to infer behavior.
        // Simpler approach: create a helper actor that will lock with the correct precomputed hash by using the actual blockhash of the stored block.

        // Deploy a Helper that will: (1) compute answer = keccak256(blockhash(storedBlock)) where storedBlock = current locker's stored block;
        // but we need storedBlock for player; however storedBlock = the block number at which lockInGuess was called + 1.
        // We can reproduce by having player call lockInGuess in a controlled sequence using inline assembly to read block.number.

        // To get the correct guess, do the following under vm.startPrank(player):
        vm.startPrank(player);
        // Re-deploy: first withdraw any prior state by making sure player has no prior guess; but we already locked once above with placeholder.
        // For robustness, we will perform the actual sequence again: (1) call lockInGuess with a computed hash using the blockhash of (block.number + 1) after advancing one block.
        // Reset by advancing to a fresh block
        vm.roll(block.number + 1);
        uint256 lockBlock = block.number; // current block for this prank
        // The contract's lockInGuess will set stored block = lockBlock + 1. We will compute the guess using blockhash(lockBlock + 1) after we advance one more block.
        // Advance to lockBlock + 1 so blockhash(lockBlock + 1) is available
        vm.roll(lockBlock + 1);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(lockBlock + 1)));
        // Now go back one block to perform lockInGuess at lockBlock so that stored block becomes lockBlock + 1 which we used to compute answer
        vm.roll(lockBlock);
        // Call lockInGuess with the correct answer and 1 ether
        c.lockInGuess{value: 1 ether}(answer);
        vm.stopPrank();

        // Advance to block > stored block so settle can be called and the blockhash(stored) is still available
        vm.roll(lockBlock + 2);

        // Now call settle as player, which should succeed and if the contract is correct, clear the stored block
        vm.prank(player);
        c.settle();

        // The general property: after a successful settle, the stored block for that player is cleared (== 0) in the reference contract.
        // We observe this by attempting to call settle again: in the reference, the second settle should revert because require(guesses[msg.sender].block != 0) fails.
        // So we try a second settle and capture whether it reverts. For the correct contract this will revert (ok==false). The mutant that left the block nonzero would allow it to proceed (ok==true) for some inputs.

        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference always causes the second settle to revert (ok == false); the mutant that omits clearing will sometimes make ok == true
        assertTrue(!ok);
    }
}

