pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz parameters: an address that will act as the player, and a uint256 offset to choose a future block.
    function testFuzz_property(address player, uint256 blockOffset) public {
        // admissible domain: nonzero address and small blockOffset so block number arithmetic is reasonable
        vm.assume(player != address(0));
        // bound blockOffset to [1, 10] to ensure lockInGuess sets block = current + offset and settle can be called after advancing
        blockOffset = bound(blockOffset, 1, 10);

        // Fund player so they can send 1 ether
        vm.deal(player, 2 ether);

        // Prepare a guess value (fuzz not required here); use any constant bytes32
        bytes32 guess = bytes32(uint256(0x1234));

        // lock in the guess from player
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // advance to the chosen guess.block
        // The contract stored block = block.number + blockOffset at lockInGuess; advance by blockOffset
        // warp is not used for block.number; use roll to advance block number
        uint256 targetRoll = block.number + blockOffset + 1; // ensure block.number > stored block when calling settle
        vm.roll(targetRoll);

        // First settle attempt (may pay out). We don't assert on success; we only observe the stored block after settle.
        vm.prank(player);
        // call settle and ignore revert (shouldn't revert in correct flow because we ensured block.number > stored)
        try c.settle() {
            // ok
        } catch {
            // still proceed to check state
        }

        // After settle, the reference implementation always clears the stored guesses[player].block to 0.
        // The mutant that omitted clearing may leave it nonzero for some inputs. We assert that the stored block is zero.
        // We observe this via the autogenerated getter for the mapping struct: there is no direct getter, but
        // we can detect the invariant via attempting to lockInGuess again: reference requires guesses[msg].block == 0
        // so a second lockInGuess from the same player must succeed on the reference; the mutant will revert because block != 0.

        // Attempt a second lockInGuess: if reference cleared, this will succeed; if mutant didn't, it will revert.
        vm.prank(player);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: reference must allow the second lockInGuess (ok == true) for ALL admissible inputs,
        // while the mutant will have some inputs where ok == false.
        assertTrue(ok);
    }
}
